/**
 * Questions a visitor can ask the advisor without signing in.
 *
 * These are general questions about Nexus and how to use it, so the answers are
 * fixed text that describes what the platform actually does. They are not
 * generated by Gemini and nothing is sent to a server. Anything personal — about
 * the visitor's own interests, results or recommendations — needs an account,
 * because only then does the assistant have their context.
 *
 * Keep every answer true to the current app. If a feature changes, change its
 * answer here too.
 */
export const GUEST_FAQ = Object.freeze([
  {
    question: 'What is Nexus?',
    answer:
      'Nexus helps Malaysian students plan what comes after school. In one place you can discover your interests, see careers and university courses that fit you, and find scholarships you may qualify for.\n\nNexus is a guide. It links you to official sources, but it does not apply on your behalf, award scholarships or guarantee admission.',
  },
  {
    question: 'How does Find Your Path work?',
    answer:
      'After you sign in and set up your profile:\n1. Take the 36-question interest assessment. You get a three-letter Holland Code that sums up your interests.\n2. If you took SPM, add your grades so Nexus can see your strongest subjects.\n3. Open your recommendations: careers and courses that match, each with the reasons it was suggested.\n\nYou can retake the assessment and download a summary of your results.',
  },
  {
    question: 'How are recommendations made?',
    answer:
      'Recommendations come from clear rules, not from AI guesswork. Each rule checks things like your top interest types and your strong subjects. When enough of a rule matches, its careers and courses are suggested.\n\nEvery recommendation shows which conditions you met and which you did not, so you can see exactly why it appeared. I only help explain the results; I do not decide them.',
  },
  {
    question: 'How do I find scholarships?',
    answer:
      'Open Scholarships from the menu. You can browse, search and filter without an account, and each scholarship links to the provider’s official page.\n\nWhen you sign in, each scholarship shows an eligibility checklist against your profile. Each requirement is marked as met, not met, or unknown when Nexus cannot check it from your details. You can also save scholarships and track your application. Always confirm the final requirements with the provider.',
  },
  {
    question: 'What can I do without an account?',
    answer:
      'You can browse Careers, Courses and Scholarships freely, including career pathways and course details.\n\nYou need a free account for the interest assessment, grade analysis, personal recommendations, scholarship eligibility checks, saved items, and asking me your own questions.',
  },
  {
    question: 'How do I create an account?',
    answer:
      'Choose Create account and enter your name, email and a password. We email you a 6-digit code; enter it on the verification page.\n\nThen a short profile setup asks about you, your education level, your SPM results if you have them, and your goals. Results and goals are optional, and you can change everything later in your profile.',
  },
  {
    question: 'What is a Holland Code?',
    answer:
      'It is a short way of describing your interests, based on six types: Realistic (hands-on), Investigative (curious problem-solving), Artistic (creative), Social (helping people), Enterprising (leading and persuading) and Conventional (organising).\n\nYour code is your top three types, for example ISA. It points to work you may enjoy; it does not measure ability or decide what you can study.',
  },
  {
    question: 'Who can see my information?',
    answer:
      'Your profile, results, recommendations, saved items and chat history are visible only to you. Database access rules enforce this, and Nexus administrators cannot view your advisory data.\n\nWhen you chat with me while signed in, a short summary such as your Holland Code and top recommendations is sent to Google’s Gemini service to write the reply. Your email and individual grades are not sent.',
  },
]);

/** @param {string} question @returns {string | null} */
export function guestAnswerFor(question) {
  return GUEST_FAQ.find((f) => f.question === question)?.answer ?? null;
}
